// GET    /posts       -> lista wszystkich postow
// GET    /posts/1     -> jeden, konkretny post
// POST   /posts       -> utworz nowy post (dane w body)
// PUT    /posts/1     -> podmien CALY post nr 1 (dane w body)
// PATCH  /posts/1     -> zaktualizuj CZESC posta nr 1 (dane w body)
// DELETE /posts/1     -> usun post nr 1 (bez body)

async function oznaczJakoUkonczone(id) {
  const odpowiedz = await fetch(`https://jsonplaceholder.typicode.com/todos/${id}`, {
    method: "PATCH", // TYLKO jedno pole - reszta zadania bez zmian
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ completed: true }),
  });

  return odpowiedz.json();
}

function utworzKlientaApi(bazowyUrl) {
  async function zapytanie(sciezka, opcje = {}) {
    const url = `${bazowyUrl}${sciezka}`;
    const konfiguracja = {
      headers: { "Content-Type": "application/json", ...opcje.headers },
      ...opcje,
    };

    if (konfiguracja.body && typeof konfiguracja.body !== "string") {
      konfiguracja.body = JSON.stringify(konfiguracja.body);
    }

    const odpowiedz = await fetch(url, konfiguracja);
    if (!odpowiedz.ok) throw new Error(`HTTP ${odpowiedz.status}`);
    return odpowiedz.json();
  }

  return {
    get: (sciezka) => zapytanie(sciezka),
    post: (sciezka, body) => zapytanie(sciezka, { method: "POST", body }),
    put: (sciezka, body) => zapytanie(sciezka, { method: "PUT", body }),
    patch: (sciezka, body) => zapytanie(sciezka, { method: "PATCH", body }),
    delete: (sciezka) => zapytanie(sciezka, { method: "DELETE" }),
  };
}

const api = utworzKlientaApi("https://jsonplaceholder.typicode.com");
api.get("/posts/1").then((post) => console.log(post.title));

