async function pobierzRownolegle() {
  async function pobierz(sciezka) {
    const odpowiedz = await fetch(`https://jsonplaceholder.typicode.com${sciezka}`);
    return odpowiedz.json();
  }

  const [uzytkownicy, posty, zadania] = await Promise.all([
    pobierz("/users?_limit=5"),
    pobierz("/posts?_limit=5"),
    pobierz("/todos?_limit=5"),
  ]);

  console.log(uzytkownicy.length, posty.length, zadania.length); // 5 5 5
}

pobierzRownolegle();

